BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "alembic_version" (
	"version_num"	VARCHAR(32) NOT NULL,
	CONSTRAINT "alembic_version_pkc" PRIMARY KEY("version_num")
);

CREATE TABLE IF NOT EXISTS "users" (
	"id"	CHAR(32) NOT NULL,
	"name"	VARCHAR(100) NOT NULL,
	"email"	VARCHAR(120) NOT NULL,
	"cpf"	VARCHAR(14) NOT NULL,
	"phone"	VARCHAR(15) NOT NULL,
	"password_hash"	VARCHAR(256) NOT NULL,
	"created_at"	DATETIME NOT NULL DEFAULT (CURRENT_TIMESTAMP),
	PRIMARY KEY("id")
);

CREATE UNIQUE INDEX IF NOT EXISTS "ix_users_cpf" ON "users" ("cpf");
CREATE UNIQUE INDEX IF NOT EXISTS "ix_users_email" ON "users" ("email");

VALUES (
    'a1b2c3d4e5f6478980123456789abcdef',
    'Usuario Teste',
    'usuario.test@email.com',
    '009.339.541-82',
    '(11) 3456-7890',
    'scrypt:32768:8:1$5jEuzK92hXqSA2bd$22aa5c999925f43036a8176542706f7ff16b41d6e84669d4552dd3c5aad34a8a3eb970344a9ed48d85d9f22bf55ed827b7f57fdc9c9831a5fb40d837df2a5f9b',
    CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS "categories" (
	"id"	CHAR(32) NOT NULL,
	"name"	VARCHAR(50) NOT NULL,
	"type"	VARCHAR(7) NOT NULL,
	"user_id"	CHAR(32) NOT NULL,
	PRIMARY KEY("id"),
	FOREIGN KEY("user_id") REFERENCES "users"("id")
);


CREATE TABLE IF NOT EXISTS "transactions" (
	"id"	CHAR(36) NOT NULL,
	"description"	VARCHAR(200) NOT NULL,
	"amount"	NUMERIC(10, 2) NOT NULL,
	"type"	VARCHAR(7) NOT NULL,
	"date"	DATE NOT NULL,
	"payment_method"	VARCHAR(10) NOT NULL,
	"user_id"	CHAR(32) NOT NULL,
	"category_id"	CHAR(32) NOT NULL,
	PRIMARY KEY("id"),
	FOREIGN KEY("category_id") REFERENCES "categories"("id"),
	FOREIGN KEY("user_id") REFERENCES "users"("id")
);

COMMIT;
